'use strict';
window.createIcon256Updater = function({say,tr,getInfo,onBusy}) {
	const u=Icon256Updates,$=id=>document.getElementById(id);
	let checking=false,installing=false,selected=null,lastCheck=0,started=false;
	try{$('update-testing').checked=localStorage.getItem('icon256-update-testing')==='true';}catch{}
	function status(text){say('update-status',text);}
	function errorText(error){return ['TypeError','AbortError','SyntaxError'].includes(error.name)?'Update check or download failed. Try again.':error.message;}
	function resetSelection(){selected=null;$('update-banner').hidden=true;$('update-install').disabled=true;}
	async function check(force=false) {
		if(checking || installing || $('update-dialog').open || (!force && Date.now()-lastCheck<3600000))return;
		checking=true;lastCheck=Date.now();resetSelection();$('update-check').disabled=true;$('update-testing').disabled=true;status('Checking for updates…');
		try {
			const info=getInfo(),catalog=await u.json(u.catalogUrl);
			const entries=u.candidates(catalog,info.ver,$('update-testing').checked);
			let invalid=false;
			for(const entry of entries) {
				try {const manifest=u.validateManifest(await u.json(u.assetBase(entry)+'manifest.json'),entry,info);selected={entry,manifest};break;}
				catch(error){invalid=true;}
			}
			if(selected){$('update-version').textContent=info.ver+' → '+selected.manifest.version;$('update-banner').hidden=false;$('update-install').disabled=false;status('Firmware update available');}
			else status(invalid?'No compatible update could be verified. Try again later.':'Your firmware is up to date.');
		}catch(error){status(errorText(error));}
		finally{checking=false;$('update-check').disabled=false;$('update-testing').disabled=false;}
	}
	$('update-check').onclick=()=>check(true);
	$('update-testing').onchange=()=>{try{localStorage.setItem('icon256-update-testing',String($('update-testing').checked));}catch{}check(true);};
	$('update-review').onclick=()=>{
		if(!selected)return;
		$('update-detail').textContent=getInfo().ver+' → '+selected.manifest.version;
		$('update-notes').href=selected.manifest.release_notes;
		say('update-result','Ready to install after your confirmation.');$('update-progress').hidden=true;$('update-dialog').showModal();
	};
	$('update-cancel').onclick=()=>{if(!installing)$('update-dialog').close();};
	$('update-dialog').addEventListener('cancel',event=>{if(installing)event.preventDefault();});
	window.addEventListener('beforeunload',event=>{if(installing){event.preventDefault();event.returnValue='';}});
	function upload(bytes,filename){
		return new Promise((resolve,reject)=>{
			const xhr=new XMLHttpRequest(),body=new FormData();body.append('update',new Blob([bytes],{type:'application/octet-stream'}),filename);
			xhr.open('POST','/update');xhr.timeout=120000;
			xhr.upload.onprogress=e=>{if(e.lengthComputable)$('update-progress').value=Math.round(e.loaded/e.total*100);};
			xhr.onload=()=>{
				if(xhr.status===200 && xhr.responseText.includes('Update successful!'))resolve();
				else if(xhr.status===401)reject(Error('Unlock firmware updates in Advanced settings first.'));
				else reject(Error('The device rejected the update. Check Advanced settings.'));
			};
			xhr.onerror=xhr.ontimeout=()=>reject(Error('Connection interrupted. Checking the installed version…'));
			xhr.send(body); // Never pass skipValidation; upstream checks metadata and OTA permissions.
		});
	}
	async function reconnect(expected,mac){
		const deadline=Date.now()+90000;
		while(Date.now()<deadline){
			await new Promise(r=>setTimeout(r,2000));
			try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),4000);let info;
				try{const r=await fetch('/json/info',{cache:'no-store',signal:controller.signal});if(!r.ok)continue;info=await r.json();}finally{clearTimeout(timer);}
				if(info.mac===mac && info.ver===expected)return true;
			}catch{}
		}
		return false;
	}
	$('update-install').onclick=async()=>{
		if(!selected || installing)return;
		const {entry,manifest}=selected,device=getInfo();
		installing=true;onBusy(true);$('update-install').disabled=true;$('update-cancel').disabled=true;$('update-check').disabled=true;$('update-testing').disabled=true;
		$('update-progress').hidden=false;$('update-progress').value=0;
		try {
			u.validateManifest(manifest,entry,device);
			if(u.compare(manifest.version,device.ver)<=0 || (!$('update-testing').checked && u.version(manifest.version).pre.length))throw Error('Invalid update metadata.');
			say('update-result','Downloading and verifying firmware…');
			const bytes=await u.download(u.assetBase(entry)+manifest.firmware.filename,manifest.firmware.size,120000,n=>$('update-progress').value=Math.round(n/manifest.firmware.size*100));
			u.validateImage(bytes,manifest);
			say('update-result','Installing firmware…');$('update-progress').value=0;
			let uploadError;
			try{await upload(bytes,manifest.firmware.filename);}catch(error){uploadError=error;if(error.message!=='Connection interrupted. Checking the installed version…')throw error;}
			say('update-result','Restarting. Waiting for your Icon256…');$('update-progress').removeAttribute('value');
			if(!await reconnect(manifest.version,device.mac))throw uploadError || Error('Could not confirm the restart. Reopen this page to check the installed version.');
			say('update-result','Update installed successfully.');status('Update installed successfully.');resetSelection();
		}catch(error){say('update-result',errorText(error));$('update-install').disabled=false;}
		finally{installing=false;onBusy(false);$('update-cancel').disabled=false;$('update-check').disabled=false;$('update-testing').disabled=false;$('update-progress').hidden=true;}
	};
	return {connected(){if(!started){started=true;check();}},resume(){if(started)check();}};
};
// AI: end
